<?php
declare(strict_types=1);namespace Liberu\Accounting\FixedAssets\Actions;use Liberu\Accounting\FixedAssets\Enums\AssetStatus;use Liberu\Accounting\FixedAssets\Exceptions\InvalidAsset;use Liberu\Accounting\FixedAssets\Models\{Asset,AssetCategory};final class AcquireAsset {public function handle(AssetCategory $category,array $a):Asset{$cost=(float)($a['cost']??0);$salvage=(float)($a['salvage_value']??0);foreach(['asset_ref','name','currency','acquired_on']as$k)if(blank($a[$k]??null))throw new InvalidAsset("Missing asset field [{$k}].");if($cost<=0||$salvage<0||$salvage>$cost)throw new InvalidAsset('Asset cost and salvage value are invalid.');return Asset::create(['team_id'=>$a['team_id']??null,'asset_ref'=>$a['asset_ref'],'name'=>$a['name'],'category_id'=>$category->getKey(),'status'=>AssetStatus::Acquired,'acquired_on'=>$a['acquired_on'],'cost'=>$cost,'salvage_value'=>$salvage,'net_book_value'=>$cost,'currency'=>strtoupper($a['currency']),'location_ref'=>$a['location_ref']??null,'custodian_ref'=>$a['custodian_ref']??null,'metadata'=>$a['metadata']??null]);}}
